'use strict'
const test = require('node:test')
const assert = require('node:assert/strict')
const fs = require('node:fs')
const path = require('node:path')
const swift = n => fs.readFileSync(path.join(__dirname, '../../ios/XDriveIOS', n + '.swift'), 'utf8')
test('4362 place Viewer stores a bounded same-window pixel offset, not media authorization', () => {
  const s = swift('NativePhotoWallComponents')
  const p = swift('NativeUnifiedSourcePhotoMap')
  assert.match(s, /struct XDriveIOSNativePhotoWallViewportAnchor: Equatable/)
  assert.match(s, /verifiedID == itemID, window == windowIndex/)
  assert.match(s, /viewportOffset <= viewportHeight - tileHeight/)
  assert.match(p, /viewerReturnViewport = openedFrame\.map/)
  assert.match(p, /key: XDriveIOSNativePhotoWallTileFramesKey\.self/)
  assert.match(p, /viewerReturnViewport\?\.alignment\(/)
  assert.match(p, /if viewerOpeningID == id && sameWindow/)
  assert.match(p, /XDriveIOSNativePhotoWallWindowPolicy\.canRestore\(/)
  assert.match(p, /viewerReturnViewport = nil/)
  assert.match(p, /XDriveIOSNativePhotoOwnerScope\.matches\(login\.owner, owner\)/)
})
